"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type TossDeckCard = {
  id: string;
  title: string;
  description?: string;
};

export type TossDeckProps = {
  cards: TossDeckCard[];
  className?: string;
  onToss?: (id: string, dir: "left" | "right") => void;
};

/**
 * Swipe to toss the top card off the deck — keep (right) or discard (left).
 */
function TossDeck({ cards, className, onToss }: TossDeckProps) {
  const [stack, setStack] = React.useState(cards);
  const drag = React.useRef<{ x: number } | null>(null);
  const [dx, setDx] = React.useState(0);

  React.useEffect(() => {
    setStack(cards);
  }, [cards]);

  const top = stack[0];

  const onPointerDown = (e: React.PointerEvent) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    drag.current = { x: e.clientX };
    setDx(0);
  };

  const onPointerMove = (e: React.PointerEvent) => {
    if (!drag.current) return;
    setDx(e.clientX - drag.current.x);
  };

  const finish = () => {
    if (!top || !drag.current) return;
    if (Math.abs(dx) > 100) {
      const dir = dx > 0 ? "right" : "left";
      onToss?.(top.id, dir);
      setStack((s) => s.slice(1));
    }
    drag.current = null;
    setDx(0);
  };

  if (!top) {
    return (
      <div
        className={cn(
          "grid h-[200px] place-items-center rounded-2xl border border-dashed border-border text-sm text-muted-foreground",
          className,
        )}
      >
        Deck cleared
      </div>
    );
  }

  return (
    <div
      className={cn(
        "relative mx-auto h-[220px] w-full max-w-sm touch-none select-none",
        className,
      )}
    >
      {stack.slice(0, 3).map((card, i) => {
        const isTop = i === 0;
        return (
          <div
            key={card.id}
            onPointerDown={isTop ? onPointerDown : undefined}
            onPointerMove={isTop ? onPointerMove : undefined}
            onPointerUp={isTop ? finish : undefined}
            onPointerCancel={isTop ? finish : undefined}
            className={cn(
              "absolute inset-x-4 top-4 rounded-2xl border border-border bg-card p-5 shadow-[var(--shadow-lift)]",
              isTop ? "cursor-grab active:cursor-grabbing" : "pointer-events-none",
            )}
            style={{
              zIndex: 10 - i,
              transform: isTop
                ? `translateX(${dx}px) rotate(${dx * 0.05}deg)`
                : `scale(${1 - i * 0.04}) translateY(${i * 10}px)`,
              opacity: 1 - i * 0.15,
            }}
          >
            <div className="text-base font-semibold">{card.title}</div>
            {card.description ? (
              <p className="mt-2 text-sm text-muted-foreground">
                {card.description}
              </p>
            ) : null}
            {isTop ? (
              <div className="mt-4 flex justify-between text-[11px] font-medium">
                <span
                  className={cn(
                    "text-destructive transition-opacity",
                    dx < -40 ? "opacity-100" : "opacity-30",
                  )}
                >
                  Toss
                </span>
                <span
                  className={cn(
                    "text-primary transition-opacity",
                    dx > 40 ? "opacity-100" : "opacity-30",
                  )}
                >
                  Keep
                </span>
              </div>
            ) : null}
          </div>
        );
      })}
    </div>
  );
}

export { TossDeck };
